<?php
namespace CloudHost247\Ovh\Products;
use WHMCS\Database\Capsule;
final class PublicCatalog
{
 public function products($kind='',$currencyId=0){$kinds=array('hosting','vps','dedicated');if($kind!==''&&!in_array($kind,$kinds,true))throw new \InvalidArgumentException('Unsupported product type.');$currency=$currencyId?Capsule::table('tblcurrencies')->where('id',(int)$currencyId)->first():Capsule::table('tblcurrencies')->where('default',1)->first();$q=Capsule::table('mod_cloudhost247_hosting_products as m')->join('tblproducts as p','p.id','=','m.whmcs_product_id')->join('tblproductgroups as g','g.id','=','p.gid')->where('p.hidden',0)->where('g.hidden',0)->whereIn('m.availability_status',array('available','limited'))->select('p.id','p.name','p.description','p.paytype','g.name as group_name','m.product_kind','m.featured','m.availability_status','m.display_order','m.specifications_json');if($kind!=='')$q->where('m.product_kind',$kind);$rows=$q->orderBy('m.display_order')->orderBy('p.order')->limit(200)->get()->all();$out=array();foreach($rows as$row){$spec=json_decode($row->specifications_json?:'{}',true);if(!is_array($spec))$spec=array();$pricing=$currency?Capsule::table('tblpricing')->where('type','product')->where('relid',$row->id)->where('currency',$currency->id)->first():null;$prices=array();if($pricing&&$row->paytype==='onetime'&&(float)$pricing->monthly>=0)$prices['one_time']=(string)$pricing->monthly;elseif($pricing&&$row->paytype==='free')$prices['free']='0';else foreach(array('monthly','quarterly','semiannually','annually','biennially','triennially')as$cycle)if($pricing&&isset($pricing->{$cycle})&&(float)$pricing->{$cycle}>=0)$prices[$cycle]=(string)$pricing->{$cycle};$out[]=array('id'=>(int)$row->id,'name'=>$row->name,'description'=>strip_tags($row->description),'group'=>$row->group_name,'kind'=>$row->product_kind,'featured'=>(bool)$row->featured,'availability'=>$row->availability_status,'specifications'=>$spec,'pricing'=>$prices,'currency'=>$currency?$currency->code:null,'prefix'=>$currency?$currency->prefix:'','suffix'=>$currency?$currency->suffix:'','cart_url'=>'cart.php?a=add&pid='.(int)$row->id);}return$out;}
}
